-- وصفات أصناف البيع من تبويب Items في شيت Menu Analysis (طلب صقر 25-11-2026).
-- Each sheet item's components and quantities become the recipe of the menu item with the same name (every branch copy).
-- Prices are NOT copied: the cost comes from the system's own raw materials and manufactured products.
-- محلي / استلام: packaging the sheet counts for one kind of order only carries "use": "dine" (ورق صواني) or "pickup"
-- (علبة، غطاء، شنطة...). Units: sheet كيلو/لتر → ×1000 g/ml, قطعة → 1 pc (a product kept by weight uses its portion grams).
-- Safe: an item that already has a recipe with components is left as it is (reported, not touched). Stock items a recipe
-- now uses are switched on for recipes (mfg = true), the same thing the screens do when an item is picked.
-- At the end each sheet item's system cost is printed next to the sheet's cost (CMP| lines in the job log).

create or replace function pg_temp.nm(text) returns text language sql immutable as
$f$ select regexp_replace(translate(coalesce($1, ''), 'أإآةى', 'اااهي'), '[^ء-ي0-9A-Za-z]', '', 'g') $f$;

create temporary table _sheet (item text, menu jsonb, pos int, ing text, raw text, unit text, qty numeric, use text, sheet_dine text, sheet_out text) on commit drop;

do $$
declare
  rid uuid;
  r record;
  m record;
  ln jsonb;
  ins int;
  skip int;
begin
  select id into rid from public.restaurants where slug = 'westeros';
  if rid is null then return; end if;

  create temporary table _res on commit drop as
  select s.*, st.id as stock_id, st.base_unit, st.last_cost,
         case when s.unit in ('كيلو', 'لتر') and st.base_unit in ('g', 'ml') then 1000
              when s.unit = 'قطعة' and st.base_unit = 'pc' then 1
              when s.unit = 'قطعة' and st.base_unit = 'g' and coalesce(st.portion, 0) > 0 then st.portion
              else null end::numeric as factor
  from _sheet s
  left join lateral (
    select x.id, x.base_unit, x.last_cost, x.portion from (
      select 1 as k, i.id, i.base_unit, i.last_cost, null::numeric as portion from public.stock_items i
       where i.restaurant_id = rid and s.raw <> '' and i.name ->> 'ar' = s.raw
      union all
      select 2, i.id, i.base_unit, i.last_cost, p.portion_grams::numeric from public.mfg_products p join public.stock_items i on i.id = p.stock_item_id
       where p.restaurant_id = rid and p.name ->> 'ar' = s.ing
      union all
      select 3, i.id, i.base_unit, i.last_cost, null from public.stock_items i
       where i.restaurant_id = rid and i.name ->> 'ar' = s.ing
    ) x order by x.k limit 1
  ) st on true;

  for r in select item, min(menu::text)::jsonb as menu, min(sheet_dine) as sd, min(sheet_out) as so from _res group by item order by item loop
    select coalesce(jsonb_agg(jsonb_build_object('itemId', g.stock_id, 'qty', g.q) || case when g.use <> '' then jsonb_build_object('use', g.use) else '{}'::jsonb end order by g.p), '[]'::jsonb)
      into ln
      from (select stock_id, use, round(sum(qty * factor), 3) as q, min(pos) as p from _res
             where item = r.item and stock_id is not null and factor is not null group by stock_id, use) g;
    ins := 0; skip := 0;
    for m in select mi.id from public.menu_items mi
              where mi.restaurant_id = rid and pg_temp.nm(mi.name ->> 'ar') in (select pg_temp.nm(t) from jsonb_array_elements_text(r.menu) t) loop
      if exists (select 1 from public.recipes x where x.restaurant_id = rid and x.owner_type = 'menu_item' and x.owner_id = m.id and x.scope_item_id is null and x.lines <> '[]'::jsonb) then
        skip := skip + 1;
      elsif jsonb_array_length(ln) > 0 then
        update public.recipes set lines = ln, updated_at = now()
         where restaurant_id = rid and owner_type = 'menu_item' and owner_id = m.id and scope_item_id is null;
        if not found then
          values (rid, 'menu_item', m.id, null, ln, 1, '');
        end if;
        ins := ins + 1;
      end if;
    end loop;
    raise notice 'CMP|%|ins=%|skip=%|dine=%|out=%|sheet=%/%|missing=%|noprice=%|unit=%', r.item, ins, skip,
      (select round(coalesce(sum(qty * factor * last_cost), 0) / 100000, 2) from _res where item = r.item and factor is not null and use <> 'pickup'),
      (select round(coalesce(sum(qty * factor * last_cost), 0) / 100000, 2) from _res where item = r.item and factor is not null and use <> 'dine'),
      r.sd, r.so,
      (select string_agg(ing, '،') from _res where item = r.item and stock_id is null),
      (select string_agg(ing, '،') from _res where item = r.item and stock_id is not null and factor is not null and coalesce(last_cost, 0) = 0),
      (select string_agg(ing || ':' || unit || '/' || base_unit, '،') from _res where item = r.item and stock_id is not null and factor is null);
  end loop;

  update public.stock_items set mfg = true
   where restaurant_id = rid and mfg = false and id in (select stock_id from _res where stock_id is not null and factor is not null);
end $$;
